		public static void AddSealCount(int id, int count) {
            SaveSealData sealData = PlayerWork.GetSealData(id);
            if (sealData.TotalCount == SealMaxCount)
                return;

            if (sealData.TotalCount + count > SealMaxCount)
                count = SealMaxCount - sealData.TotalCount;

