            int returnable = sealData.TotalCount - sealData.Count;
            if (returnable == 0)
                return;

            if (sealData.Count + count > sealData.TotalCount)
                count = returnable;

            sealData.Count += count;
            PlayerWork.SetSealData(id, sealData);
        }
