		public static global::UnityEngine.Vector3 Convert2DPosition(int x, int y, bool isFront) {
            Vector3 pos = Vector3.zero;
            int radius = isFront ? Capsule2DCalcFrontRadius : Capsule2DCalcBackRadius;
            int splitAngle = isFront ? Capsule2DCalcFrontSplitAngle : Capsule2DCalcBackSplitAngle;

            float theta = (Capsule2DCalcCenterThetaAngle - splitAngle * y) * Mathf.Deg2Rad;
            int phiAngle = splitAngle * x + (isFront ? Capsule2DCalcCenterFrontPhiAngle : Capsule2DCalcCenterBackPhiAngle);
            float phi = (phiAngle < 0 ? phiAngle + 360.0f : phiAngle) * Mathf.Deg2Rad;

            pos = new Vector3(radius * Mathf.Sin(theta) * Mathf.Sin(phi), radius * Mathf.Cos(theta), radius * Mathf.Sin(theta) * Mathf.Cos(phi));
            pos.x = Mathf.Round(pos.x * 100.0f) / 100.0f;
            pos.y = Mathf.Round(pos.y * 100.0f) / 100.0f;
            pos.z = Mathf.Round(pos.z * 100.0f) / 100.0f;
            return pos;
        }
